import{_ as d}from"./chunks/1c4467b41961bde0fa1aee34061b93d9.B03u6GuX.js";import{_ as e,c as a,a2 as r,o}from"./chunks/framework.BnrAgU0Y.js";const m=JSON.parse('{"title":"Langflow中的模型组件","description":"Langflow中的模型组件","frontmatter":{"title":"Langflow中的模型组件","description":"Langflow中的模型组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-models.md","filePath":"langflow/components-models.md"}'),h={name:"langflow/components-models.md"};function n(l,t,i,p,s,u){return o(),a("div",null,t[0]||(t[0]=[r('<h1 id="langflow中的模型组件" tabindex="-1">Langflow中的模型组件 <a class="header-anchor" href="#langflow中的模型组件" aria-label="Permalink to &quot;Langflow中的模型组件&quot;">​</a></h1><p>模型组件使用大型语言模型生成文本。</p><p>请参阅您特定组件的文档以获取有关参数的更多信息。</p><h2 id="在流程中使用模型组件" tabindex="-1">在流程中使用模型组件 <a class="header-anchor" href="#在流程中使用模型组件" aria-label="Permalink to &quot;在流程中使用模型组件&quot;">​</a></h2><p>模型组件接收输入和提示以生成文本，而生成的文本会发送到输出组件。</p><p>模型输出也可以发送到<strong>语言模型</strong>接口，并且传递到<strong>解析数据</strong>组件中，输出结果能够被解析为结构化<a href="./URL.html">数据</a>对象。</p><p>此示例中包含了 OpenAI 模型在聊天机器人流程中的应用。如需更多信息，请参阅<a href="./URL.html">基础提示流程</a>。</p><p><img src="'+d+'" alt=""></p><h2 id="ai-ml-api" tabindex="-1">AI/ML API <a class="header-anchor" href="#ai-ml-api" aria-label="Permalink to &quot;AI/ML API&quot;">​</a></h2><p>该组件使用 AIML API 创建一个 ChatOpenAI 模型实例。</p><p>有关更多信息，请参见 <a href="https://docs.aimlapi.com/" target="_blank" rel="noreferrer">AIML 文档</a>。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>max_tokens</td><td>Integer</td><td>生成的最大 token 数。设置为 0 表示无限制。范围：0-128000。</td></tr><tr><td>model_kwargs</td><td>Dictionary</td><td>模型的附加关键字参数。</td></tr><tr><td>model_name</td><td>String</td><td>要使用的 AIML 模型名称。选项在 <code>AIML_CHAT_MODELS</code> 中预定义。</td></tr><tr><td>aiml_api_base</td><td>String</td><td>AIML API 的基础 URL。默认值为 <code>https://api.aimlapi.com</code>。</td></tr><tr><td>api_key</td><td>SecretString</td><td>用于模型的 AIML API 密钥。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出随机性。默认值：<code>0.1</code>。</td></tr><tr><td>seed</td><td>Integer</td><td>控制任务的可重复性。</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个使用指定参数配置的 ChatOpenAI 实例。</td></tr></tbody></table><h2 id="amazon-bedrock" tabindex="-1">Amazon Bedrock <a class="header-anchor" href="#amazon-bedrock" aria-label="Permalink to &quot;Amazon Bedrock&quot;">​</a></h2><p>该组件使用 Amazon Bedrock 大型语言模型（LLMs）生成文本。</p><p>有关更多信息，请参阅 <a href="https://docs.aws.amazon.com/bedrock" target="_blank" rel="noreferrer">Amazon Bedrock 文档</a>。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><p><a href="#inputs-1" class="hash-link" aria-label="Direct link to Inputs" title="Direct link to Inputs">​</a></p><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model_id</td><td>String</td><td>要使用的 Amazon Bedrock 模型的 ID。选项包括各种模型。</td></tr><tr><td>aws_access_key</td><td>SecretString</td><td>用于身份验证的 AWS 访问密钥。</td></tr><tr><td>aws_secret_key</td><td>SecretString</td><td>用于身份验证的 AWS 秘密密钥。</td></tr><tr><td>credentials_profile_name</td><td>String</td><td>要使用的 AWS 凭证配置文件的名称（高级）。</td></tr><tr><td>region_name</td><td>String</td><td>AWS 区域名称。默认值：<code>us-east-1</code>。</td></tr><tr><td>model_kwargs</td><td>Dictionary</td><td>模型的其他关键词参数（高级）。</td></tr><tr><td>endpoint_url</td><td>String</td><td>自定义的 Bedrock 服务端点 URL（高级）。</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>配置了指定参数的 ChatBedrock 实例。</td></tr></tbody></table><h2 id="anthropic" tabindex="-1">Anthropic <a class="header-anchor" href="#anthropic" aria-label="Permalink to &quot;Anthropic&quot;">​</a></h2><p>该组件允许使用 Anthropic Chat 和语言模型生成文本。</p><p>有关更多信息，请参阅 <a href="https://docs.anthropic.com/en/docs/welcome" target="_blank" rel="noreferrer">Anthropic 文档</a>。</p><h3 id="inputs-2" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-2" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>max_tokens</td><td>Integer</td><td>生成的最大 token 数量。设置为 0 表示不限制 token。默认值: <code>4096</code>。</td></tr><tr><td>model</td><td>String</td><td>要使用的 Anthropic 模型的名称。选项包括各种 Claude 3 模型。</td></tr><tr><td>anthropic_api_key</td><td>SecretString</td><td>用于身份验证的 Anthropic API 密钥。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。默认值: <code>0.1</code>。</td></tr><tr><td>anthropic_api_url</td><td>String</td><td>Anthropic API 的端点。如果未指定，则默认为 <code>https://api.anthropic.com</code>（高级设置）。</td></tr><tr><td>prefill</td><td>String</td><td>引导模型响应的预填内容（高级设置）。</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个根据指定参数配置的 ChatAnthropic 实例。</td></tr></tbody></table><h2 id="azure-openai" tabindex="-1">Azure OpenAI <a class="header-anchor" href="#azure-openai" aria-label="Permalink to &quot;Azure OpenAI&quot;">​</a></h2><p>该组件使用 Azure OpenAI LLM 生成文本。</p><p>欲了解更多信息，请参见 <a href="https://learn.microsoft.com/en-us/azure/ai-services/openai/" target="_blank" rel="noreferrer">Azure OpenAI 文档</a>。</p><h3 id="inputs-3" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-3" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>Model Name</td><td>Model Name</td><td>指定用于文本生成的 Azure OpenAI 模型名称。</td></tr><tr><td>Azure Endpoint</td><td>Azure Endpoint</td><td>您的 Azure 端点，包括资源。</td></tr><tr><td>Deployment Name</td><td>Deployment Name</td><td>指定部署的名称。</td></tr><tr><td>API Version</td><td>API Version</td><td>指定要使用的 Azure OpenAI API 版本。</td></tr><tr><td>API Key</td><td>API Key</td><td>您的 Azure OpenAI API 密钥。</td></tr><tr><td>Temperature</td><td>Temperature</td><td>指定采样温度。默认值为 <code>0.7</code>。</td></tr><tr><td>Max Tokens</td><td>Max Tokens</td><td>指定生成的最大令牌数量。默认值为 <code>1000</code>。</td></tr><tr><td>Input Value</td><td>Input Value</td><td>指定用于文本生成的输入文本。</td></tr><tr><td>Stream</td><td>Stream</td><td>指定是否从模型流式传输响应。默认值为 <code>False</code>。</td></tr></tbody></table><h3 id="输出-1" tabindex="-1">输出 <a class="header-anchor" href="#输出-1" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>使用指定参数配置的 AzureOpenAI 实例。</td></tr></tbody></table><h2 id="cohere" tabindex="-1">Cohere <a class="header-anchor" href="#cohere" aria-label="Permalink to &quot;Cohere&quot;">​</a></h2><p>该组件使用 Cohere 的语言模型生成文本。</p><p>欲了解更多信息，请参见 <a href="https://cohere.ai/" target="_blank" rel="noreferrer">Cohere 文档</a>。</p><h3 id="inputs-4" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-4" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>Cohere API Key</td><td>Cohere API Key</td><td>您的 Cohere API 密钥。</td></tr><tr><td>Max Tokens</td><td>Max Tokens</td><td>指定要生成的最大令牌数。默认为 <code>256</code>。</td></tr><tr><td>Temperature</td><td>Temperature</td><td>指定采样温度。默认为 <code>0.75</code>。</td></tr><tr><td>Input Value</td><td>Input Value</td><td>指定用于文本生成的输入文本。</td></tr></tbody></table><h3 id="outputs-2" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-2" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个配置了指定参数的 Cohere 模型实例。</td></tr></tbody></table><h2 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to &quot;DeepSeek&quot;">​</a></h2><p>该组件使用 DeepSeek 的语言模型生成文本。</p><p>有关更多信息，请参阅 <a href="https://api-docs.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek 文档</a>。</p><h3 id="inputs-5" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-5" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>max_tokens</td><td>Integer</td><td>生成的最大 token 数。设置为 <code>0</code> 表示无限制。范围：<code>0-128000</code>。</td></tr><tr><td>model_kwargs</td><td>Dictionary</td><td>模型的附加关键字参数。</td></tr><tr><td>json_mode</td><td>Boolean</td><td>如果为 <code>True</code>，则输出 JSON，无论是否传递了 schema。</td></tr><tr><td>model_name</td><td>String</td><td>使用的 DeepSeek 模型。默认值：<code>deepseek-chat</code>。</td></tr><tr><td>api_base</td><td>String</td><td>API 请求的基础 URL。默认值：<code>https://api.deepseek.com</code>。</td></tr><tr><td>api_key</td><td>SecretString</td><td>用于验证的 DeepSeek API 密钥。</td></tr><tr><td>temperature</td><td>Float</td><td>控制响应的随机性。范围：<code>[0.0, 2.0]</code>。默认值：<code>1.0</code>。</td></tr><tr><td>seed</td><td>Integer</td><td>用于随机数生成的初始化数。使用相同的 seed 整数可获得更可重复的结果，使用不同的 seed 数字可获得更随机的结果。</td></tr></tbody></table><h3 id="outputs-3" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-3" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个配置了指定参数的 ChatOpenAI 示例。</td></tr></tbody></table><h2 id="google-生成式-ai" tabindex="-1">Google 生成式 AI <a class="header-anchor" href="#google-生成式-ai" aria-label="Permalink to &quot;Google 生成式 AI&quot;">​</a></h2><p>此组件使用 Google 的生成式 AI 模型生成文本。</p><p>欲了解更多信息，请参阅 <a href="https://cloud.google.com/vertex-ai/docs/" target="_blank" rel="noreferrer">Google 生成式 AI 文档</a>。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>Google API Key</td><td>Google API Key</td><td>您用于 Google 生成式 AI 的 Google API 密钥。</td></tr><tr><td>Model</td><td>Model</td><td>要使用的模型名称，例如 <code>“gemini-pro”</code>。</td></tr><tr><td>Max Output Tokens</td><td>Max Output Tokens</td><td>要生成的最大 tokens 数量。</td></tr><tr><td>Temperature</td><td>Temperature</td><td>使用此温度进行推理。</td></tr><tr><td>Top K</td><td>Top K</td><td>考虑前 K 个最可能的 tokens 集合。</td></tr><tr><td>Top P</td><td>Top P</td><td>在采样时考虑 tokens 的最大累积概率。</td></tr><tr><td>N</td><td>N</td><td>为每个提示生成的聊天完成数。</td></tr></tbody></table><h3 id="outputs-4" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-4" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个使用指定参数配置的 <code>ChatGoogleGenerativeAI</code> 示例。</td></tr></tbody></table><h2 id="groq" tabindex="-1">Groq <a class="header-anchor" href="#groq" aria-label="Permalink to &quot;Groq&quot;">​</a></h2><p>该组件使用 Groq 的语言模型生成文本。</p><p>有关更多信息，请参阅 <a href="https://groq.com/" target="_blank" rel="noreferrer">Groq 文档</a>。</p><h3 id="inputs-6" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-6" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>groq_api_key</td><td>SecretString</td><td>Groq API 的 API 密钥。</td></tr><tr><td>groq_api_base</td><td>String</td><td>API 请求的基本 URL 路径。默认值： <code>https://api.groq.com</code>（高级）。</td></tr><tr><td>max_tokens</td><td>Integer</td><td>要生成的最大 tokens 数（高级）。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。范围： <code>[0.0, 1.0]</code>。默认值： <code>0.1</code>。</td></tr><tr><td>n</td><td>Integer</td><td>每个提示生成的聊天完成数（高级）。</td></tr><tr><td>model_name</td><td>String</td><td>要使用的 Groq 模型名称。选项是从 Groq API 动态获取的。</td></tr></tbody></table><h3 id="outputs-5" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-5" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个配置了指定参数的 ChatGroq 实例。</td></tr></tbody></table><h2 id="hugging-face-api" tabindex="-1">Hugging Face API <a class="header-anchor" href="#hugging-face-api" aria-label="Permalink to &quot;Hugging Face API&quot;">​</a></h2><p>此组件使用 Hugging Face 的语言模型生成文本。</p><p>欲了解更多信息，请参见 <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face 文档</a>。</p><h3 id="输入项" tabindex="-1">输入项 <a class="header-anchor" href="#输入项" aria-label="Permalink to &quot;输入项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>Endpoint URL</td><td>Endpoint URL</td><td>Hugging Face 推理 API 端点的 URL。</td></tr><tr><td>Task</td><td>Task</td><td>指定文本生成的任务。</td></tr><tr><td>API Token</td><td>API Token</td><td>认证所需的 API 令牌。</td></tr><tr><td>Model Kwargs</td><td>Model Kwargs</td><td>模型的附加关键字参数。</td></tr><tr><td>Input Value</td><td>Input Value</td><td>文本生成的输入文本。</td></tr></tbody></table><h2 id="lmstudio" tabindex="-1">LMStudio <a class="header-anchor" href="#lmstudio" aria-label="Permalink to &quot;LMStudio&quot;">​</a></h2><p>该组件使用 LM Studio 的本地语言模型生成文本。</p><p>欲了解更多信息，请参阅 <a href="https://lmstudio.ai/" target="_blank" rel="noreferrer">LM Studio 文档</a>。</p><h3 id="inputs-7" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-7" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>base_url</td><td>String</td><td>LM Studio 所在的 URL。默认值：<code>&quot;http://localhost:1234&quot;</code>。</td></tr><tr><td>max_tokens</td><td>Integer</td><td>响应中生成的最大 token 数量。默认值：<code>512</code>。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。范围：<code>[0.0, 2.0]</code>。默认值：<code>0.7</code>。</td></tr><tr><td>top_p</td><td>Float</td><td>通过 nucleus sampling 控制多样性。范围：<code>[0.0, 1.0]</code>。默认值：<code>1.0</code>。</td></tr><tr><td>stop</td><td>List[String]</td><td>遇到时将停止生成的字符串列表（高级）。</td></tr><tr><td>stream</td><td>Boolean</td><td>是否流式传输响应。默认值：<code>False</code>。</td></tr><tr><td>presence_penalty</td><td>Float</td><td>惩罚重复的 token。范围：<code>[-2.0, 2.0]</code>。默认值：<code>0.0</code>。</td></tr><tr><td>frequency_penalty</td><td>Float</td><td>惩罚频繁出现的 token。范围：<code>[-2.0, 2.0]</code>。默认值：<code>0.0</code>。</td></tr></tbody></table><h3 id="outputs-6" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-6" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>使用指定参数配置的LMStudio实例。</td></tr></tbody></table><h2 id="maritalk" tabindex="-1">Maritalk <a class="header-anchor" href="#maritalk" aria-label="Permalink to &quot;Maritalk&quot;">​</a></h2><p>该组件使用 Maritalk 大型语言模型（LLMs）生成文本。</p><p>欲了解更多信息，请参见 <a href="https://www.maritalk.com/" target="_blank" rel="noreferrer">Maritalk 文档</a>。</p><h3 id="inputs-8" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-8" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>max_tokens</td><td>Integer</td><td>生成的最大 token 数量。设置为 <code>0</code> 表示无限制。默认值：<code>512</code>。</td></tr><tr><td>model_name</td><td>String</td><td>使用的 Maritalk 模型名称。选项：<code>sabia-2-small</code>、<code>sabia-2-medium</code>。默认值：<code>sabia-2-small</code>。</td></tr><tr><td>api_key</td><td>SecretString</td><td>用于认证的 Maritalk API 密钥。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出结果的随机性。范围：<code>[0.0, 1.0]</code>。 默认值：<code>0.5</code>。</td></tr><tr><td>endpoint_url</td><td>String</td><td>Maritalk API 的访问端点。默认值：<code>https://api.maritalk.com</code>。</td></tr></tbody></table><h3 id="输出-2" tabindex="-1">输出 <a class="header-anchor" href="#输出-2" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个通过指定参数配置的 ChatMaritalk 实例。</td></tr></tbody></table><h2 id="mistral" tabindex="-1">Mistral <a class="header-anchor" href="#mistral" aria-label="Permalink to &quot;Mistral&quot;">​</a></h2><p>该组件使用 MistralAI 的 LLMs（大语言模型）生成文本。</p><p>有关更多信息，请参见 <a href="https://docs.mistral.ai/" target="_blank" rel="noreferrer">Mistral AI 文档</a>。</p><h3 id="inputs-9" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-9" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>max_tokens</td><td>Integer</td><td>生成的最大 tokens 数量。设为 0 表示无限制 tokens（高级选项）。</td></tr><tr><td>model_name</td><td>String</td><td>使用的 Mistral AI 模型名称。选项包括<code>open-mixtral-8x7b</code>、<code>open-mixtral-8x22b</code>、<code>mistral-small-latest</code>、<code>mistral-medium-latest</code>、<code>mistral-large-latest</code>和<code>codestral-latest</code>。默认值：<code>codestral-latest</code>。</td></tr><tr><td>mistral_api_base</td><td>String</td><td>Mistral API 的基础 URL。默认值为 <code>https://api.mistral.ai/v1</code>（高级选项）。</td></tr><tr><td>api_key</td><td>SecretString</td><td>用于身份验证的 Mistral API 密钥。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。默认值：0.5。</td></tr><tr><td>max_retries</td><td>Integer</td><td>API 调用的最大重试次数。默认值：5（高级选项）。</td></tr><tr><td>timeout</td><td>Integer</td><td>API 调用的超时时间（以秒为单位）。默认值：60（高级选项）。</td></tr><tr><td>max_concurrent_requests</td><td>Integer</td><td>最大并发 API 请求数量。默认值：3（高级选项）。</td></tr><tr><td>top_p</td><td>Float</td><td>核采样参数。默认值：1（高级选项）。</td></tr><tr><td>random_seed</td><td>Integer</td><td>随机数生成的种子。默认值：1（高级选项）。</td></tr><tr><td>safe_mode</td><td>Boolean</td><td>启用内容生成的安全模式（高级选项）。</td></tr></tbody></table><h3 id="outputs-7" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-7" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>具有指定参数配置的 ChatMistralAI 实例。</td></tr></tbody></table><h2 id="novita-ai" tabindex="-1">Novita AI <a class="header-anchor" href="#novita-ai" aria-label="Permalink to &quot;Novita AI&quot;">​</a></h2><p>该组件使用 Novita AI 的语言模型生成文本。</p><p>更多信息，请参见 <a href="https://novita.ai/docs/model-api/reference/llm/llm.html?utm_source=github_langflow&amp;utm_medium=github_readme&amp;utm_campaign=link" target="_blank" rel="noreferrer">Novita AI 文档</a>。</p><h3 id="inputs-10" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-10" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>api_key</td><td>SecretString</td><td>您的 Novita AI API 密钥。</td></tr><tr><td>model</td><td>String</td><td>要使用的 Novita AI 模型的 ID。</td></tr><tr><td>max_tokens</td><td>Integer</td><td>生成的最大标记数。设置为 0 表示不限数量。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。范围：[0.0, 1.0]。默认值：0.7。</td></tr><tr><td>top_p</td><td>Float</td><td>控制核心采样。范围：[0.0, 1.0]。默认值：1.0。</td></tr><tr><td>frequency_penalty</td><td>Float</td><td>控制频率惩罚。范围：[0.0, 2.0]。默认值：0.0。</td></tr><tr><td>presence_penalty</td><td>Float</td><td>控制存在惩罚。范围：[0.0, 2.0]。默认值：0.0。</td></tr></tbody></table><h3 id="输出-3" tabindex="-1">输出 <a class="header-anchor" href="#输出-3" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个配置有指定参数的 Novita AI 模型实例。</td></tr></tbody></table><h2 id="nvidia" tabindex="-1">NVIDIA <a class="header-anchor" href="#nvidia" aria-label="Permalink to &quot;NVIDIA&quot;">​</a></h2><p>此组件使用 NVIDIA 大型语言模型（LLMs）生成文本。</p><p>有关更多信息，请参见 <a href="https://developer.nvidia.com/generative-ai" target="_blank" rel="noreferrer">NVIDIA AI 文档</a>。</p><h3 id="inputs-11" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-11" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>max_tokens</td><td>Integer</td><td>生成的最大tokens数量。设置为 <code>0</code> 表示无限制tokens（高级设置）。</td></tr><tr><td>model_name</td><td>String</td><td>使用的NVIDIA模型的名称。默认值：<code>mistralai/mixtral-8x7b-instruct-v0.1</code>。</td></tr><tr><td>base_url</td><td>String</td><td>NVIDIA API的基础URL。默认值：<code>https://integrate.api.nvidia.com/v1</code>。</td></tr><tr><td>nvidia_api_key</td><td>SecretString</td><td>用于认证的NVIDIA API密钥。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。默认值：<code>0.1</code>。</td></tr><tr><td>seed</td><td>Integer</td><td>控制任务再现性的种子值（高级设置）。默认值：<code>1</code>。</td></tr></tbody></table><h3 id="输出-4" tabindex="-1">输出 <a class="header-anchor" href="#输出-4" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个使用指定参数配置的 ChatNVIDIA 实例。</td></tr></tbody></table><h2 id="ollama" tabindex="-1">Ollama <a class="header-anchor" href="#ollama" aria-label="Permalink to &quot;Ollama&quot;">​</a></h2><p>该组件使用 Ollama 的语言模型生成文本。</p><p>有关更多信息，请参见 <a href="https://ollama.com/" target="_blank" rel="noreferrer">Ollama 文档</a>。</p><h3 id="inputs-12" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-12" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>Base URL</td><td>Base URL</td><td>Ollama API 的端点 (Endpoint)。</td></tr><tr><td>Model Name</td><td>Model Name</td><td>要使用的模型名称。</td></tr><tr><td>Temperature</td><td>Temperature</td><td>控制模型响应的创造性。</td></tr></tbody></table><h3 id="outputs-8" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-8" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>配置有指定参数的 Ollama 模型（Ollama model）实例。</td></tr></tbody></table><h2 id="openai" tabindex="-1">OpenAI <a class="header-anchor" href="#openai" aria-label="Permalink to &quot;OpenAI&quot;">​</a></h2><p>该组件使用OpenAI的语言模型生成文本。</p><p>有关详细信息，请参见 <a href="https://beta.openai.com/docs/" target="_blank" rel="noreferrer">OpenAI 文档</a>。</p><h3 id="inputs-13" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-13" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>api_key</td><td>SecretString</td><td>你的 OpenAI API 密钥。</td></tr><tr><td>model</td><td>String</td><td>所使用的 OpenAI 模型名称。选项包括 &quot;gpt-3.5-turbo&quot; 和 &quot;gpt-4&quot;。</td></tr><tr><td>max_tokens</td><td>Integer</td><td>生成的最大 token 数量。设为 0 表示无限制。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。范围：[0.0, 1.0]。默认值：0.7。</td></tr><tr><td>top_p</td><td>Float</td><td>控制 nucleus sampling（核采样）。范围：[0.0, 1.0]。默认值：1.0。</td></tr><tr><td>frequency_penalty</td><td>Float</td><td>控制频率惩罚。范围：[0.0, 2.0]。默认值：0.0。</td></tr><tr><td>presence_penalty</td><td>Float</td><td>控制存在惩罚。范围：[0.0, 2.0]。默认值：0.0。</td></tr></tbody></table><h3 id="输出-5" tabindex="-1">输出 <a class="header-anchor" href="#输出-5" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>配置了指定参数的 OpenAI 模型（OpenAI model）实例。</td></tr></tbody></table><h2 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h2><p>此组件使用 OpenRouter 的统一 API 来生成文本，适用于来自不同提供商的多个 AI 模型。</p><p>有关更多信息，请参阅 <a href="https://openrouter.ai/docs" target="_blank" rel="noreferrer">OpenRouter 文档</a>。</p><h3 id="inputs-14" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-14" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>api_key</td><td>SecretString</td><td>您的 OpenRouter API 密钥，用于身份验证。</td></tr><tr><td>site_url</td><td>String</td><td>您的网站 URL，用于 OpenRouter 排名（高级）。</td></tr><tr><td>app_name</td><td>String</td><td>您的应用名称，用于 OpenRouter 排名（高级）。</td></tr><tr><td>provider</td><td>String</td><td>使用的 AI 模型提供商。</td></tr><tr><td>model_name</td><td>String</td><td>用于聊天生成的具体模型。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。范围：[0.0, 2.0]。默认值：0.7。</td></tr><tr><td>max_tokens</td><td>Integer</td><td>要生成的最大 token 数量（高级）。</td></tr></tbody></table><h3 id="输出-6" tabindex="-1">输出 <a class="header-anchor" href="#输出-6" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个配置了指定参数的 ChatOpenAI 实例。</td></tr></tbody></table><h2 id="困惑度" tabindex="-1">困惑度 <a class="header-anchor" href="#困惑度" aria-label="Permalink to &quot;困惑度&quot;">​</a></h2><p>此组件使用 Perplexity 的语言模型生成文本。</p><p>欲了解更多信息，请参见 <a href="https://perplexity.ai/" target="_blank" rel="noreferrer">Perplexity 文档</a>。</p><h3 id="inputs-15" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-15" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model_name</td><td>String</td><td>要使用的 Perplexity 模型名称。选项包括各种 Llama 3.1 模型。</td></tr><tr><td>max_output_tokens</td><td>Integer</td><td>要生成的最大 token 数量。</td></tr><tr><td>api_key</td><td>SecretString</td><td>用于认证的 Perplexity API 密钥。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。默认值：0.75。</td></tr><tr><td>top_p</td><td>Float</td><td>采样时要考虑的最大累积概率的 token（高级设置）。</td></tr><tr><td>n</td><td>Integer</td><td>为每个提示生成的对话补全数量（高级设置）。</td></tr><tr><td>top_k</td><td>Integer</td><td>要考虑的 top-k 采样的 top token 数量。必须为正数（高级设置）。</td></tr></tbody></table><h3 id="outputs-9" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-9" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个配置了指定参数的 ChatPerplexity 实例。</td></tr></tbody></table><h2 id="qianfan" tabindex="-1">Qianfan <a class="header-anchor" href="#qianfan" aria-label="Permalink to &quot;Qianfan&quot;">​</a></h2><p>此组件使用 Qianfan 的语言模型生成文本。</p><p>欲了解更多信息，请参见 <a href="https://github.com/baidubce/bce-qianfan-sdk" target="_blank" rel="noreferrer">Qianfan 文档</a>。</p><h2 id="sambanova" tabindex="-1">SambaNova <a class="header-anchor" href="#sambanova" aria-label="Permalink to &quot;SambaNova&quot;">​</a></h2><p>该组件使用 SambaNova 大型语言模型 (LLM) 生成文本。</p><p>欲了解更多信息，请参见 <a href="https://cloud.sambanova.ai/" target="_blank" rel="noreferrer">Sambanova Cloud 文档</a>。</p><h3 id="输入-1" tabindex="-1">输入 <a class="header-anchor" href="#输入-1" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>sambanova_url</td><td>String</td><td>API请求的基础URL路径。默认值：<code>https://api.sambanova.ai/v1/chat/completions</code>。</td></tr><tr><td>sambanova_api_key</td><td>SecretString</td><td>你的SambaNova API密钥。</td></tr><tr><td>model_name</td><td>String</td><td>使用的Sambanova模型的名称。选项包括各种Llama模型。</td></tr><tr><td>max_tokens</td><td>Integer</td><td>生成的最大token数量。设置为0表示不限制token数量。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。范围：[0.0, 1.0]。默认值：0.07。</td></tr></tbody></table><h3 id="outputs-10" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-10" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>配置了指定参数的SambaNova模型实例。</td></tr></tbody></table><h2 id="vertexai" tabindex="-1">VertexAI <a class="header-anchor" href="#vertexai" aria-label="Permalink to &quot;VertexAI&quot;">​</a></h2><p>该组件使用 Vertex AI 大型语言模型（LLM）生成文本。</p><p>欲了解更多信息，请参阅 <a href="https://cloud.google.com/vertex-ai" target="_blank" rel="noreferrer">Google Vertex AI 文档</a>。</p><h3 id="inputs-16" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-16" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>credentials</td><td>文件</td><td>JSON 凭证文件。留空以回退到环境变量。文件类型：JSON。</td></tr><tr><td>model_name</td><td>字符串</td><td>要使用的 Vertex AI 模型名称。默认值：&quot;gemini-1.5-pro&quot;。</td></tr><tr><td>project</td><td>字符串</td><td>项目 ID（高级）。</td></tr><tr><td>location</td><td>字符串</td><td>Vertex AI API 的位置。默认值：&quot;us-central1&quot;（高级）。</td></tr><tr><td>max_output_tokens</td><td>整数</td><td>要生成的最大 token 数量（高级）。</td></tr><tr><td>max_retries</td><td>整数</td><td>API 调用的最大重试次数。默认值：1（高级）。</td></tr><tr><td>temperature</td><td>浮点数</td><td>控制输出的随机性。默认值：0.0。</td></tr><tr><td>top_k</td><td>整数</td><td>保留用于 top-k 过滤的最高概率词汇 token 数量（高级）。</td></tr><tr><td>top_p</td><td>浮点数</td><td>保留用于 nucleus 采样的参数最高概率词汇 token 的累积概率。默认值：0.95（高级）。</td></tr><tr><td>verbose</td><td>布尔值</td><td>是否打印详细输出。默认值：False（高级）。</td></tr></tbody></table><h3 id="outputs-11" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-11" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个配置了指定参数的 ChatVertexAI 实例。</td></tr></tbody></table><h2 id="xai" tabindex="-1">xAI <a class="header-anchor" href="#xai" aria-label="Permalink to &quot;xAI&quot;">​</a></h2><p>该组件使用 xAI 模型（例如 <a href="https://x.ai/grok" target="_blank" rel="noreferrer">Grok</a>）生成文本。</p><p>欲了解更多信息，请参阅 <a href="https://x.ai/" target="_blank" rel="noreferrer">xAI 文档</a>。</p><h3 id="inputs-17" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-17" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>max_tokens</td><td>Integer</td><td>生成的最大token数量。设置为 <code>0</code> 表示不限制。范围：<code>0-128000</code>。</td></tr><tr><td>model_kwargs</td><td>Dictionary</td><td>模型的额外关键字参数。</td></tr><tr><td>json_mode</td><td>Boolean</td><td>如果为 <code>True</code>，则无论是否传递架构输出JSON。</td></tr><tr><td>model_name</td><td>String</td><td>使用的xAI模型。默认值：<code>grok-2-latest</code>。</td></tr><tr><td>base_url</td><td>String</td><td>API请求的基础URL。默认值：<code>https://api.x.ai/v1</code>。</td></tr><tr><td>api_key</td><td>SecretString</td><td>用于认证的xAI API密钥。</td></tr><tr><td>temperature</td><td>Float</td><td>控制输出的随机性。范围：<code>[0.0, 2.0]</code>。默认值：<code>0.1</code>。</td></tr><tr><td>seed</td><td>Integer</td><td>控制作业的可重复性。</td></tr></tbody></table><h3 id="outputs-19" tabindex="-1">输出 <a class="header-anchor" href="#outputs-19" aria-label="Permalink to &quot;输出 {#outputs-19}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>LanguageModel</td><td>一个使用指定参数配置的 ChatOpenAI 实例。</td></tr></tbody></table>',157)]))}const g=e(h,[["render",n]]);export{m as __pageData,g as default};
